WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS session_start_flag_tier, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(method)) AS method_list, SIZE(COLLECT_SET(method)) AS num_methods FROM sessions_payments GROUP BY 1 ORDER BY session_start_flag_tier NULLS LAST
